// Hand-authored gate driver — two_oracle_agreement gate.
// Primitive: ccitt
// Freeze gate: for each `tests/fixtures/ccitt/*.ccfix` fixture X,
// asserts `to_canonical(parse(X))` matches the cached
// `<X>.canonical` sidecar byte-for-byte. The sidecar was
// generated by `Feedstock/PDF/Fixtures/ccitt/generate_fixtures.py`,
// which runs libtiff (via Pillow) and mupdf as two independent
// CCITT codepaths and only commits a fixture when both oracles
// produce identical decoded rasters — the gate therefore needs no
// runtime oracle, the agreement is baked into the sidecar.

#[path = "../../src/internal/ccitt.rs"]
mod ccitt;

use std::fs;
use std::path::{Path, PathBuf};

const FIXTURE_EXT: &str = "ccfix";

fn corpus_dir() -> PathBuf {
    if let Ok(env_dir) = std::env::var("SPECDEV_CORPUS_DIR") {
        if !env_dir.is_empty() {
            return PathBuf::from(env_dir);
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("ccitt")
}

fn collect_fixtures(dir: &Path) -> Vec<PathBuf> {
    let mut fixtures: Vec<PathBuf> = fs::read_dir(dir)
        .expect("read corpus dir")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.is_file())
        .filter(|p| {
            p.extension().and_then(|s| s.to_str()) == Some(FIXTURE_EXT)
        })
        .collect();
    fixtures.sort();
    fixtures
}

#[test]
fn two_oracle_agreement_over_corpus() {
    let dir = corpus_dir();
    assert!(
        dir.is_dir(),
        "corpus dir not found: {} \
         (set SPECDEV_CORPUS_DIR or vendor tests/fixtures/ccitt/)",
        dir.display()
    );

    let fixtures = collect_fixtures(&dir);
    assert!(
        !fixtures.is_empty(),
        "no .{} fixtures under {}",
        FIXTURE_EXT,
        dir.display()
    );

    let mut failures: Vec<String> = Vec::new();
    let mut checked = 0usize;
    for path in &fixtures {
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let canonical_path = path.with_extension("canonical");
        if !canonical_path.is_file() {
            failures.push(format!(
                "{name}: missing sidecar {}",
                canonical_path.display()
            ));
            continue;
        }
        let input = fs::read(path).expect("read fixture");
        let expected = fs::read_to_string(&canonical_path).expect("read sidecar");

        let actual = match ccitt::parse(&input) {
            Ok(img) => ccitt::to_canonical(&img),
            Err(e) => {
                failures.push(format!("{name}: parse failed: {e}"));
                continue;
            }
        };

        if actual != expected {
            // First-line divergence pointer, matching the C++ driver.
            let n = actual.len().min(expected.len());
            let mut pos = 0usize;
            let mut line = 1usize;
            let mut line_start = 0usize;
            let a_bytes = actual.as_bytes();
            let e_bytes = expected.as_bytes();
            while pos < n && a_bytes[pos] == e_bytes[pos] {
                if a_bytes[pos] == b'\n' {
                    line += 1;
                    line_start = pos + 1;
                }
                pos += 1;
            }
            let line_at = |s: &str, start: usize| -> String {
                let bytes = s.as_bytes();
                let end = bytes[start..]
                    .iter()
                    .position(|&b| b == b'\n')
                    .map(|o| start + o)
                    .unwrap_or(bytes.len());
                let len = (end - start).min(200);
                s[start..start + len].to_string()
            };
            failures.push(format!(
                "{name}: line {}: expected '{}' | got '{}'",
                line,
                line_at(&expected, line_start),
                line_at(&actual, line_start)
            ));
        }
        checked += 1;
    }

    eprintln!(
        "ccitt two_oracle_agreement: checked={} failed={}",
        checked,
        failures.len()
    );
    if !failures.is_empty() {
        for f in &failures {
            eprintln!("MISMATCH {f}");
        }
        panic!("{} ccitt fixtures failed", failures.len());
    }
}

// ------------------------------------------------------------
// Encoder smoke gates — round-trip a handful of synthesised
// 1bpp rasters through encode_group3 / encode_group4 + decode.
// The Rust-target overlay ships these encoders ahead of the
// cpp / csharp peers; the .ccfix freeze-gate corpus stays
// decode-only because the PDF spec only mandates decoding.
// ------------------------------------------------------------

fn make_bits<F: FnMut(u32, u32) -> bool>(
    columns: u32,
    rows: u32,
    mut pixel: F,
) -> Vec<u8> {
    let stride = columns.div_ceil(8) as usize;
    let mut bits = vec![0u8; stride * rows as usize];
    for y in 0..rows {
        for x in 0..columns {
            if pixel(x, y) {
                bits[y as usize * stride + (x / 8) as usize] |=
                    0x80 >> (x % 8);
            }
        }
    }
    bits
}

fn encode_round_trip(bits: &[u8], columns: u32, rows: u32, k: i8) {
    let encoded = match k {
        0 => ccitt::encode_group3(bits, columns, rows).expect("encode_group3"),
        -1 => ccitt::encode_group4(bits, columns, rows).expect("encode_group4"),
        _ => panic!("only k in {{0,-1}} supported"),
    };
    let params = ccitt::Params {
        k,
        end_of_line: k == 0,
        encoded_byte_align: false,
        end_of_block: k == -1,
        black_is_1: true,
        columns,
        rows,
        damaged_rows_before_error: 0,
    };
    let decoded = ccitt::decode(&encoded, &params).expect("decode");
    assert_eq!(decoded.width, columns);
    assert_eq!(decoded.height, rows);
    assert_eq!(decoded.bits, bits, "round-trip failed (k={k})");
}

#[test]
fn encode_group3_round_trip_smoke() {
    encode_round_trip(&make_bits(64, 4, |_, _| true), 64, 4, 0);
    encode_round_trip(&make_bits(64, 4, |_, _| false), 64, 4, 0);
    encode_round_trip(&make_bits(128, 8, |x, _| (x / 8) % 2 == 0), 128, 8, 0);
    encode_round_trip(&make_bits(32, 32, |x, y| x != y), 32, 32, 0);
    encode_round_trip(&make_bits(2000, 2, |_, _| true), 2000, 2, 0);
    encode_round_trip(&make_bits(2400, 1, |_, _| false), 2400, 1, 0);
    encode_round_trip(&make_bits(5000, 1, |_, _| false), 5000, 1, 0);
}

#[test]
fn encode_group4_round_trip_smoke() {
    encode_round_trip(&make_bits(64, 4, |_, _| true), 64, 4, -1);
    encode_round_trip(&make_bits(64, 4, |_, _| false), 64, 4, -1);
    encode_round_trip(&make_bits(64, 16, |_, y| (y / 4) % 2 == 0), 64, 16, -1);
    encode_round_trip(&make_bits(128, 8, |x, _| (x / 8) % 2 == 0), 128, 8, -1);
    encode_round_trip(&make_bits(32, 32, |x, y| x != y), 32, 32, -1);
    encode_round_trip(
        &make_bits(32, 32, |x, y| !((x % 5 == 0) && (y % 7 == 0))),
        32,
        32,
        -1,
    );
    encode_round_trip(
        &make_bits(2400, 2, |x, y| (x + y) % 2 == 0),
        2400,
        2,
        -1,
    );
}

#[test]
fn encode_rejects_zero_dimensions() {
    let err = ccitt::encode_group3(&[], 0, 1).unwrap_err();
    assert!(matches!(err, ccitt::EncodeError::InvalidColumns));
    let err = ccitt::encode_group4(&[], 8, 0).unwrap_err();
    assert!(matches!(err, ccitt::EncodeError::InvalidRows));
}

#[test]
fn encode_rejects_bits_length_mismatch() {
    let err = ccitt::encode_group3(&[0u8; 3], 16, 1).unwrap_err();
    assert!(matches!(
        err,
        ccitt::EncodeError::BitsLengthMismatch { expected: 2, got: 3 }
    ));
}
